function useCardProgress(count) {
  const refs = useRef([]);
  const [active, setActive] = useState(0);

  useEffect(() => {
    let raf = null;

    const compute = () => {
      const vh = window.innerHeight;
      let current = 0;

      refs.current.forEach((el, i) => {
        if (!el) return;
        const rect = el.getBoundingClientRect();
        if (rect.top <= vh * 0.12) current = i;

        const inner = el.querySelector("[data-card-inner]");
        if (!inner) return;

        const distanceToCover = rect.top;
        const coverProgress = Math.min(
          Math.max(1 - distanceToCover / vh, 0),
          1
        );

        const isLast = i === count - 1;
        const scale = isLast ? 1 : 1 - coverProgress * 0.08;
        const dim = isLast ? 0 : coverProgress * 0.55;

        inner.style.transform = `scale(${scale})`;
        inner.style.setProperty("--dim", dim.toFixed(3));
      });

      setActive(current);
      raf = null;
    };

    const onScroll = () => {
      if (raf === null) raf = requestAnimationFrame(compute);
    };

    compute();
    window.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", onScroll);
    return () => {
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", onScroll);
      if (raf) cancelAnimationFrame(raf);
    };
  }, [count]);

  return { refs, active };
}

